CHANGELOG = '## [0.247.0] - walk the chosen layout from the panel\n\n**Increment 5 of the no-AI authoring loop** (the factory\'s `docs/AUTHORING_LOOP.md`; roadmap 315).\n\n### Added\n- **`walk_level`** (`packages/service/walking.py`). The legs `make` runs after its pick, then `walk`, each its own\n  process:\n  - the brief and shell-lock gates, recorded by `panel` and noted as automatic steps, not reviews; the choice of\n    layout must already be the designer\'s;\n  - `run --art --gameplay`, with progress from the job index (`layouts.index_progress`, now shared with\n    generation);\n  - `walk` without `--play`: the export into the workspace\'s own `exports/`, the preview project, its import, and\n    its traversal self-check.\n\n  The worker opens no window; it returns the preview\'s folder and the workspace\'s Godot. The result names the\n  design revision and layout, and `builds/revision_<n>.walk.json` records them with the self-check\'s verdict. A\n  preview is never an accepted export (roadmap 317 copies a snapshot out of the workspace).\n- **Walk level** on the Level tab. It shows what the walk is of and the self-check\'s verdict, then opens the\n  preview with `godot --path <preview>`, or says where it is when no Godot is recorded.\n\n### Measured\n- The 0.246.0 trial design\'s chosen layout (seed 9205), walked through the worker in 8 min 42 s: art, lighting and\n  gameplay, an export with a light bake (141 models lightmapped, 65.5 s), the preview built and its self-check\n  passed. It is named "Panel Trial, revision 1, layout seed 9205".\n\n### Tests\n- `tests/service/test_walking.py` (fails on 0.246.0):\n  - the legs in order; the gates by `panel`, not reviews; no `--play`;\n  - the verdict, revision and layout named, and the walk recorded;\n  - a self-check with findings still hands the preview over;\n  - no layouts and no choice refused before anything runs; a failed art leg refused by name.\n- `apps/godot/tests/test_level_walk.gd`: the walk\'s label and verdict, and the command that opens the preview,\n  with no window opened.\n\n'
OLD_VERSION, NEW_VERSION = '0.246.0', '0.247.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
